		{
			"ARENA_RULE_TEXT_3",
			"上頂樓戰鬥規則：",
			""
		},
		{
			"ARENA_RULE_TEXT_4",
			"1.每天晚9點整通過排名獲得獎勵，通過信件發放.|2.頂樓中戰鬥自動進行，玩家不能手動釋放技能.|3.頂樓戰鬥中，所有戰姬血量及治療效果經過相同幅度上調.|4.若戰鬥勝利，且防守方的排名高於進攻方，則將雙方排名對調.|5.若戰鬥超時則存活戰姬多的一方獲勝.|6.每天每個玩家可以免費發起戰鬥5次，每天淩晨5點整重置次數.|7.每次戰鬥後，進攻方玩家將獲得一個10分鐘的冷卻時間.|8.若本服最高等級玩家達到60級，則週五20:30前頂樓排名達到前200名、同時本週頂樓挑戰次數滿10次的玩家（前5名除外），週末將會開啟特殊模式頂樓，特殊模式開啟時間為週五20:30到週日20:30，并擁有全新的規則與戰鬥方式.",
			""
		},
		{
			"ARENA_RULE_TEXT_5",
			"歷史最高排名獎勵規則：",
			""
		},
		{
			"ARENA_RULE_TEXT_6",
			"當玩家成功升至自己的歷史最高排名時，發放一次性鑽石獎勵.|最高排名獎勵根據進步幅度而不同，每次至少獲得1鑽石.|最高排名獎勵通過彈窗提示，直接發放.",
			""
		},
		{
			"ARENA_RULE_TEXT_7",
			"每日排名獎勵規則：",
			""
		},
		{
			"ARENA_RULE_TEXT_8",
			"根據每天排名結算時的排名發放獎勵信件，詳細獎勵規則如下：",
			""
		},
		{
			"ARENA_RULE_ITEM_TITLE_1",
			"第%d名",
			""
		},
		{
			"ARENA_RULE_ITEM_TITLE_2",
			"第%d名-第%d名",
			""
		},
		{
			"PEAK_ARENA_RULE_TEXT_1",
			"你的鬥牛本服排名是%d名，保持當前排名（第%d至第%d名），可領獎勵為：",
			""
		},
		{
			"PEAK_ARENA_RULE_TEXT_3",
			"鬥牛戰鬥規則：",
			""
		},
		{
			"PEAK_ARENA_RULE_TEXT_4",
			"1.每週日晚上22點整發放本服排名獎勵，通過信件發放，本服排名根據跨服排名產生，獎勵結算后不會重置積分和排名。|2.鬥牛戰鬥自動進行，玩家不能手動施放技能。|3.在鬥牛中，所有戰姬血量及治療效果經過相同幅度上調。|4.玩家可以隨時調整自己的防守陣容，見習組（鬥牛跨服排名5001以下）需要設置3隊，高階組（鬥牛跨服排名501-5000）為5隊，大師組（鬥牛跨服排名1-500）為7隊，每隊戰姬至少1人。|5.見習組采用3局2勝制，高階組采用5局3勝制，大師組采用7局4勝制。|6.消滅對方全部戰姬獲得勝利。|7.戰鬥超時，存活戰姬多的一方取得勝利。|8.存活戰姬數量一樣時，總傷害高的一方獲得勝利。|9.總傷害一樣時，防守方獲得勝利。|10.見習組采用積分制，高階組和大師組采用排名制。|11.見習組鬥牛的勝者會獲得一定積分，敗者會損失一定積分，高階組和大師組鬥牛獲勝則會交換排名。|12.見習組獲得的積分與挑戰方和被挑戰方的積分差有關，積分差越大，獲得或損失的積分越多。|13.每天每個玩家可以免費挑戰對手10次，每天淩晨5點整重置次數。|14.每次挑戰後，發起挑戰的玩家進入冷卻時間，見習組為1分鐘，高階組和大師組為5分鐘。|15.大師組的玩家會隱藏后3支隊伍，高階組的玩家會隱藏后2支隊伍，見習組的玩家將不會隱藏隊伍。|16.每天晚上22點到第二天早上8點無法進行鬥牛。|17.見習組分爲三個段位，三段和二段的晉級需要達到對應的晉級積分，見習組一段到高階組和高階組到大師組需要參加晉級賽。|18.晉級賽規則詳見“晉級規則”。",
			""
		},
