		{
			"borrow_rule",
			"1. 任何學妹和萌寵都可以借出，但不是所有學妹和萌寵都會被租用@2. 社團會給借出的學妹和萌寵辛苦費，時間越長收入越多@3. 學妹和萌寵借出後，至少要等待30分鐘才能收回@4. 社團成員可以支付金幣，租用其他社員借出的學妹和萌寵@5. 每天只能向同一名社員租用一名學妹和一名萌寵@6. 社團會根據學妹和萌寵的實力決定每位學妹和萌寵的辛苦費@7. 租用費的一部分上交社團，其餘的由借出者獲得@8. 玩家的vip等級越高，可借出的學妹越多@9. 租用的學妹可參加劇情，全國制霸，隨堂測驗，歷史測驗的戰鬥@10. 每場戰鬥只可租用一位學妹或萌寵，無論勝負，租用費不返還@11. 租用學妹與社團成員自己的同名學妹不能同時上場@12. 每次全國制霸只能租用一位學妹，她會為你奮戰到底@13. 在劇情，隨堂測驗，歷史測驗中，租用學妹通關後，將最多獲得兩星@14.達到vip4後可以租借高於自身學院等級1等的戰姬，並且隨著vip等級的提高，可租借戰姬等級也會隨之提高，租借上限為高於自身5等。",
