			"1.從第七章開始,每一章都是一個獨立的社團活動@2.每個社團活動的開啟都需要消耗一定的社團活躍@3.社長和副社長可以選擇重置活動,每次重置需要消耗相同的社團活躍@4.社團成員可以輪流挑戰同一活動關卡,關卡內敵人血量不回復@5.每個社團成員每天可以進入每個社團活動挑戰兩次,最多可以攻克一個關卡.在同一關卡迎戰新的敵人時,剩餘時間不重置@6.爲了不影響其他社團成員的體驗，每次挑選戰姬不能超過1分鐘，戰鬥時間不能超過3分鐘.@7.每天淩晨五點至八點是社團活動休整時間,期間無法進行社團活動的戰鬥@8.每天挑戰社團活動後可以通過每日任務獲得一定的社團徽章,社團徽章可以在禮物兌換處兌換獎品@9.每當完成社團活動時,全體社團成員都可以獲得一定的社團徽章,如果在重置活動後的七天內完成,全體社團成員可以獲得更多的徽章獎勵@10.社團活動將記錄每個社團成員打出的單場戰鬥最高傷害,排名靠前的成員可以在活動完成時獲得徽章獎勵@11.完成每個關卡最後一擊的成員也可以獲得一定的徽章獎勵@12.每場社團活動的戰鬥結束時,社團會根據挑戰者當次的戰鬥的輸出傷害,給予一定的金幣獎勵@13.在計算傷害輸出時,活動最終boss血量按200%計算@14.社團活動將會在重置或通關時，按照進度發放對應數量的社團硬幣獎勵給社團所有被記錄的成員，社團硬幣可以在社團商店中購買對應裝備.@15.玩家造成的最高傷害排名會為玩家帶來額外的社團硬幣獎勵加成.@16.限時通關後，將會提高基礎的社團硬幣獎勵.@17.社團活動重置時,將會記錄當前工會所有成員，未被記錄的成員將無法挑戰社團活動，也不會獲得本次社團活動的獎勵.@18.社團BOSS不受位移技能影響，但是可以造成傷害，曹洪的換位技能可以正常換位,部分戰姬繞後技能無法繞後BOSS張遼、關羽、程昱。",
			""
		},
