		{
			"CHRISTMAS_RULE_TEXT2",
			"“召喚師哥哥，還記得過幾天是什麽日子嗎？”聖誕妹妹閃爍著水靈靈的眼睛望著，“討厭啦！是聖誕節要到啦！”聖誕妹妹臉紅紅的繼續說：“我要舉辦一個狂歡派對，邀請所有的學妹都來參加！”@爲了準備好這次派對，心情雀躍的聖誕妹妹很早就開始爬上爬下，張燈結綵啦，可她手裡還缺少聖誕禮包，聖誕禮圈，聖誕襪，聖誕球等等--召喚師哥哥們如果能幫忙收集就好啦！@召喚師哥哥們，可以幫聖誕妹妹到各個地方（指定副本）尋找派對用品嗎？收集到正確和足夠多的派對用品交給人家，就可以領取活動獎勵哦！如果交給人家聖誕禮包、聖誕禮圈、聖誕襪、聖誕球各一個的話，還可以點亮許願星喲！@對啦，人家上次買飲料的時候忘了把聖誕帽拿回來了，召喚師哥哥能幫人家找找嘛，人家會用大禮包來和哥哥兌換的喲！",
