			""
		},
		{
			"REGION_ARENA_RULE3",
			"1、競技模式為賽季制度，每個賽季持續45天。|2、在每個跨服競技賽有26個等級，從LV.1晉級到LV.MAX王者。|3、每次勝利獲得一顆寶石，低於20級時連勝4次及以上獲得2顆寶石|4、寶石數滿了即可晉級為下一級。|5、當升至LV.16後對戰失敗會降低一顆寶石，直到降級為LV.15。|6、當升至LV.MAX時失敗將不會再降級，開始計算王者積分|7、在LV.MAX王者戰勝的對手越強，獲得的王者積分越多。|8、賽季結束後，戰績等級達到LV.15會獲得參與獎。|9、賽季結束後，戰績等級達到LV.MAX會獲得王者獎勵。|10、賽季結束後，排行榜第一名的玩家會獲得冠軍獎勵，頭像持續時間為45天，到期將自動消失。|11、賽季獎勵以郵件形式發放。|12、每天前10次匹配無論勝負都會獲得額外跨服幣獎勵。|13、練習模式沒有勝利獎勵與失敗懲罰。|14、連續防守勝利3次將獲得一顆寶石，連續防守失敗3次將扣除一顆寶石。|15、若戰鬥時間未能消滅全部敵人，則存活戰姬數量多的一方獲勝。|18、若存活戰姬數量相同，則輸出傷害多的一方獲勝。|19、已召喚的所有戰姬等級和品階將被拉平到100等紅色+1滿裝備滿附魔狀態。|20、保留戰姬星級和覺醒狀態。|21、圖書架，課程，徽章和課本增加屬性在跨服競技場的戰鬥不生效，洗煉屬性在跨服競技場的戰鬥不生效。|22、競技模式下，完成跨服任務可以獲得王者徽記，徽記可用於兌換跨服競技場能力。|23、可兌換的能力包括：提升一名戰姬星級；覺醒一名戰姬；僱傭一名戰姬。|24、每隔20小時刷新一個任務，最多擁有3個任務。|25、所有的王者徽記和兌換的能力當前賽季結束後清零。",
