		{
			"KITE_KING_RULE",
			"1、活動期間儲值只要滿足條件立即獲得對應風箏贈送數量，不限制次數。|2、必須要一次性儲值到達獎勵條件才能獲得贈送的風箏，一次性儲值超過最高檔位3000鑽的也按3000鑽檔位來計算。|3、一次性儲值達到最高檔位3000，其他二個檔位的獎勵也將獲取一次，以此類推若儲值600鑽，300鑽檔位的獎勵也將獲得。|4、放風箏後需要其他玩家進行領取，選擇尋找的地點後才可獲得鑽石獎勵。選對地點比選錯地點鑽石獎勵高。|5、學院等級大於等於20級放出任意風箏10個以上才能參加競選|6、活動期間都可以報名，報名成功後將出現在競選列表中|7、活動列表中的順序將按票數高低來排，低於50名開外的將不顯示|8、每人每天可以投一次票，前4天投票都將獲得金幣獎勵，後3天將獲得鑽石獎勵，獎勵數量隨進行天數增加會有所提高|9、除了贏取玩家的投票以外還可以通過放風箏增加投票數量|10、玩家每投一次等於2票，放出迷你風箏等於1票，經典風箏等於2票，豪華風箏等於10票。|11、活動將於最後1天22點進行結算，結算後根據排名通過信箱發放獎勵。",
