			"BEACH_RULE",
			"海灘章魚大樂鬥規則：|1. 玩家每天有一次免費挑戰大樂鬥的機會。|2. 每次進入大樂鬥將會獲得15次免費的章魚攻擊次數（可用鑽石購買攻擊次數），每次攻擊Boss，將會消耗一次攻擊次數（攻擊和暴擊攻擊都只消耗一次攻擊次數）。|3. 進入後，玩家有三種章魚攻擊方式：粉紅章魚，冰藍章魚和火焰章魚。每隻粉紅章魚造成1點傷害，每隻冰藍章魚造成3點傷害，每隻火焰章魚造成5點傷害。|4. 當玩家啟動暴擊狀態後，所造成的傷害值將變為3倍。|5. 玩家每次只能連接同一種章魚，連接可以是相鄰的直線或斜線。連接的數量越多，造成的傷害越高。|6. 當Boss被擊敗時，將會得到Boss守護的寶箱。點擊寶箱即可獲得獎勵。",
