		{
			"REGION_MISSION_RULE",
			"1、跨服競技模式為賽季制度，每個賽季持續45天。|2、只有本服當日競技場前五名玩家才有資格參加明日的跨服競技場。|3、跨服競技場會在每日20點根據玩家排名發放對應獎勵和王者積分。|4、每日20點至21點無法進行挑戰。|5、賽季結束後，總王者積分排行前一百名的玩家會獲得頭像框獎勵。|6、賽季結束後，排行榜第一名的玩家會獲得冠軍頭像獎勵，頭像持續時間為45天，到期將自動消失。|7、賽季獎勵以郵件形式發放。|8、賽季結束後，累計王者積分最多的三十二名玩家將自動入圍季後賽，爭奪季後賽總冠軍。|9、已召喚的所有戰姬等級和品階將被拉平到90等橙色+2滿裝備滿附魔狀態。|10、保留戰姬星級和覺醒狀態。|11、圖書架和課本增加屬性在跨服競技場的戰鬥生效，洗煉屬性在跨服競技場的戰鬥不生效。|12、系統每日都會發放王者硬幣，王者硬幣可用於購買跨服競技場的皮膚或道具。|13、參賽者將會根據名次先後發放王者硬幣；未參賽者將根據本服參賽玩家所爭奪到的最高名次發放王者硬幣。|14、未參賽者可以支持出征的玩家，支持後會獲得30點體力獎勵，每天只能支持一次。|15、每日20點至21點無法進行支持。",
			""
