		{
			"ANNIVERSARY_THIEF_RULE_TITLE",
			"驅逐小偷活動規則",
			""
		},
		{
			"ANNIVERSARY_THIEF_RULE_TEXT",
			"    盛大的學園一週年感謝祭活動即將來臨，可是就在這個時候，用來舉辦活動的東西卻被狡猾的小偷偷走了！為了確保活動能夠順利舉辦，就請各位學長學妹們一起打敗小偷，奪回重要的東西吧！||1.小偷只在白天活動，玩家每天8點-22點可以前去驅逐小偷。|2.每人每天可以免費參與3次驅逐小偷的戰鬥。|3.在每天對抗小偷的戰鬥中，對小偷造成的最高一次傷害計入歷史總傷害。|4.每驅逐一次小偷，都會獲得小偷包包裡掉落的許願燭與其他獎勵。|5.小偷被成功驅逐後，根據對小偷的歷史總傷害排名，學園會對前50名發放獎勵。|6.每天22點結算當天對小偷合計造成的傷害。|7.小偷十分狡猾，任何控制效果都對她不起作用，但是她依然會受到中毒、破甲等減益魔法的影響。",
			""
		},
