		{
			"ANNIVERSARY_JIGSAW_RULE_TEXT",
			"1.一週年感謝祭期間，完成任務獲取神秘拼圖，當拼圖完成一定條件後，就可以獲得豪華大禮！|2.點擊拼圖版面上的每塊拼圖，可以查看獲得該拼圖的具體方式。|3.當獲得一塊拼圖後，拖動拼圖到達相應位置，就可以拼好拼圖。每拼好一塊拼圖都能獲得一份拼圖獎勵。|4.當拼好的拼圖滿足了獲取獎勵的條件之後，才能夠獲得對應獎勵。只是獲得了拼圖碎片而不拼好是不能達成條件的喲！|5.在某些拼圖碎片中，隱藏著神秘的文字。找到這些藏有神秘文字的拼圖並且拼好，就能夠獲得神秘大獎！",
