			""
		},
		{
			"INCUBUS_RULE",
			"1、學院等級達到90等才能守護學妹。|2、最多同時登場5名戰姬。|3、戰鬥過程中會出現隨機任務，完成/失敗後會獲得獎勵/懲罰性Buff。|4、每天可守護3次學妹，VIp玩家可花費一定鑽石可以額外購買一定守護次數。|5、學妹會因為流氓的侵擾而不斷減少血量，每擊敗一波敵人則會為學妹恢復一定生命，學妹生命降至0時戰鬥結束。|6、擊敗流氓團夥會幾率掉落被守護學妹的契約書及稀有道具集點。|7、守護學妹需要消耗體力，每名被守護學妹的體力消耗依次為：第一次30點體力，第二次60點體力，第三次90點體力，第四次120點體力，之後該學妹的守護消耗體力永久固定為120點。|8、進入關卡需要至少選擇五名首發戰姬，首發戰姬即一開始必定出現在上陣可選戰姬區域內。|9、選擇完首發戰姬後，可選擇支援戰姬，支援戰姬會自動補充至可上陣戰姬區域。|10、支援戰姬的出現順序隨機。|11、戰姬上陣需要消耗能量，能量會隨著時間的推移逐漸增加。|12、總有一些忙於修煉的戰姬不願多管閒事，因此個別戰姬會被“禁用”並不可選（嗯…其實是這些戰姬對流氓的威懾力太強，她們會導致流氓不敢現身犯罪，流氓不欺辱學妹我們還怎麼收集學妹契約書？）。|13、守護學妹的恐怖氛圍會導致上陣戰姬不斷的損失生命值。|14、當前上陣的戰姬數量越多，下一次派遣戰姬上陣消耗的能量就越高。|15、在守護過程中退出，僅會扣除5點“手續費體力”，但守護過程中所獲得的一切道具都會消失。|16、挑戰守護任意學妹後，當日可消耗掃蕩卷對該學妹進行掃蕩，掃蕩波數即為手動挑戰的最高波數。|17、掃蕩券消耗數量等於掃蕩的最高波數，掃蕩券不足時，可以用鑽石代替。",
