		},
		{
			"PLAYOFF_RULE_TEXT2",
			"1、本賽季結束後，積分排名前三十二位的玩家將自動參加季後賽。|2、通過刷分作弊獲得王者積分的，經核實會被取消參賽資格。",
			""
