		{
			"PLAYOFF_RULE_TEXT3",
			"季後賽比賽規則：",
			""
		},
		{
			"PLAYOFF_RULE_TEXT4",
			"1、比賽分為小組賽、八強賽、四強賽、半決賽、決賽五個階段。|2、小組賽階段，所有32名選手隨機分為8組，四人一組，每人都要和其他三位選手對戰一局。|3、小組賽的戰鬥採用三局兩勝的戰鬥方式。|4、每個小組中勝場數最高的兩個選手可以進入八強賽，如果勝場數相同，按報名時間先後決定出線資格。|5、八強賽：所有出線的16強選手互相穿插配對進行淘汰賽，決出八強，A組的第一名與B組的第二名對戰，B組的第一名與A組的第二名對戰，以此類推。|6、四強賽：八強選手分為兩組進行淘汰賽，採用三局兩勝的戰鬥決定四強名單。|7、半決賽：四強選手分為兩組進行淘汰賽，採用三場三局兩勝的戰鬥決定二強名單，每場戰鬥間隔為20分鐘。|8、決賽：二強選手進行三場三局兩勝的戰鬥決定冠亞軍，每場戰鬥間隔為20分鐘。|9、每場比賽都有固定的時間舉行，選手需要在指定的時間上線並處於跨服競技場介面參加比賽。|10、如果選手沒來（未在規定時間內點擊準備戰鬥），則系統開始自動戰鬥。|11、為保證季後賽的公平，玩家使用的戰姬均為100級紅一滿附魔覺醒狀態，洗練屬性無效，活動中心課本屬性無效。|12、請選手挑選網絡環境好的地方參賽。",
			""
		},
		{
			"PLAYOFF_RULE_TEXT5",
			"季後賽支持規則：",
			""
		},
		{
			"PLAYOFF_RULE_TEXT6",
			"1、從報名結束到半決賽前，玩家都可以支持自己喜歡的選手。|2、60級及以上的玩家都可以支持選手。|3、根據玩家等級不同，只要支持的玩家小組賽出線或者淘汰賽獲勝一次就可以獲得一定的基礎支持獎勵，基礎獎金跟戰隊等級相關，戰隊等級越高，基礎獎金越高。|4、自己支持的選手再次在小組賽出線，八強賽勝出，四強賽勝出，半決賽勝出，決賽勝出，支持獎金都將翻倍。|5、例如，路人甲支持選手A，A小組賽出線、八強賽勝利、但是四強階段被淘汰，則路人甲的獎金為支持獎金的兩倍（小組賽出線獲得支持獎金，八強賽勝利獎金翻倍）。|6、每個玩家最高可獲得16倍基礎獎金（支持的選手在所有階段全部勝出）。|7、如果你支持的選手被淘汰，你也可以繼續支持其他選手。但翻倍計數將重新計算，半決賽後將無法更換或支持選手。|8、獎勵的金幣將在季後賽全部結束後通過郵件發放。",
			""
