			"PLAYOFF_RULE_TEXT8",
			"1、冠軍選手可以獲得10000鑽石獎勵，2000萬金幣獎勵。|2、亞軍選手可獲得5000鑽石獎勵，1000萬金幣獎勵。|3、四強選手可獲得2000鑽石獎勵，400萬金幣獎勵。|4、八強選手可獲得1000鑽石獎勵，200萬金幣獎勵。|5、16強選手可獲得500鑽石獎勵，100萬金幣獎勵。|6、32強選手可獲得200鑽石獎勵，40萬金幣獎勵。|7、每個選手只根據自己的最好成績領取一份獎勵，不能重複領取。",
