		{
			"STAR_TREASURE_RULE_TEXT",
			"    中秋之夜，嫦娥與玉兔正在月宮中賞月。忽然，眼尖的玉兔發現神秘的夜空中竟然隱藏了很多寶物，於是她決定前往深空中一探究竟！||1.星空尋寶總共分為9層，在每一層探索都能夠找到各不相同的特殊物品獎勵。|2.每探索一次都會消耗一個當前裝備的探索道具，不同的探索道具可以起到不同的探索效果，比如一次探索多個格子，或使探索到的道具翻倍等。|3.探索道具可以通過活動道具商店購買，也可以在探索的過程中隨機獲得。同時月餅大賞活動中通過每日登錄也可以獲得一些探索道具，請不要錯過！|4.在擁有道具處點擊不同的道具圖標，可以切換選擇不同的探索道具。|5.在每一層的探索中發現並且點擊下一層入口，才能夠前往下一層繼續探索。|6.通過重新開始按鈕可以放棄當前的探索進度，從第一層開始重新探索。需要注意的是，每一層獨有的特殊物品不會重複獲得，在發現一次過後就沒有了喔。",
