			"    萬聖夜即將來臨，各位學長們是準備在家中等待午夜神秘來客的造訪，還是盛裝出發，期待捧著糖果籃子滿載而歸呢？咦，咚咚咚，是誰在敲門？原來是萬聖巫女在請求你幫助她煉制魔法藥劑！親愛的學長，快去收集各種魔法材料，來幫助巫女煉制各種萬聖節的搞怪魔法物品吧！||1.活動期間，通過或掃蕩普通精英副本，或是每在遊戲中消費達到300鑽石，就可以獲得各種魔法材料。|2.通過按照指定的配方來將魔法材料煉造成各種魔法物品，就可以獲得一定數量的魔法元素，所獲得的魔法元素數量為消耗的魔法材料之和。|3.每收集指定數量的魔法元素，就能夠獲得萬聖巫女為你準備的小禮物，大量的契約書、美味的萬聖南瓜派，還有萬聖專屬頭像等你來拿！當魔法元素達到200以上時，每收集50魔法元素就能獲得一份隨機的神秘大禮，有機會開出稀有皮膚大獎喲！|4.當單個服務器中所有人收集的魔法元素到達全服目標後，所有參與活動並且收集了至少200魔法元素的學長就會獲得一份豐厚的禮物，請千萬不要錯過！",
