		{
			"PARADISE_RULE_TEXT",
			"   學院旁邊的空地上突然新開了一家名為幻想鄉的遊樂場，據說是校長的某個老朋友所建，但是遊樂場一夜之間突然建立讓大家感到非常的詭異，於是學妹們決定去樂園一探究竟！可是在每個遊樂設施前，等待著他們的卻是一個個強勁的boss，這個遊樂園里一定有著什麽秘密！|1、65級以上的玩家可以參與幻想鄉boss的挑戰。|2、boss刷新後，每人每日可以免費挑戰5次幻想鄉boss。|3、活動當日對boss造成傷害最高的一次傷害計入排行榜。|4、boss刷新後的當天晚上22點幻想鄉結算獎勵，為方便今日結算，園長會提前兩分鐘對幻想鄉進行關閉哦。|5、活動當日22點按照你對boss造成的最高傷害排名發放獎勵。|6、社團成員對boss造成的最高傷害總和計入幻想鄉社團榜。|7、22點按照社團傷害總和排行榜給社團發放社團活躍度獎勵。|8、幻想鄉的boss每失去一定的血量就會疊加一層狂暴狀態。|9、幻想鄉可以租借戰姬。|10、獎勵獲得的樂園幣可以到樂園商店購買各種道具。|11、活動當日22點你對boss造成的最高傷害的20％將折成金幣獎勵與排名獎勵一起發放。|12、幻想鄉的boss可被擊殺。|13、當今日幻想鄉關閉後，樂園將進入時長為一日的休整期，並會在隔一日後的8:00重新開放。|14、合作模式需要3名玩家一起完成，房主必須派遣寵物|15、合作模式不會消耗每日次數|16、在合作模式下，玩家不可派遣戰鬥力過低的戰姬上場|17、合作模式下獲得的總成績會被算作每個玩家自己此次的成績|18、合作模式會根據排名，額外獲得一份獎勵",
