		{
			"ACTIVITY_SINGLE_RULE_TEXT",
			"1.需要兩名玩家間建立夥伴關係才能參加本活動，沒有夥伴時脫團目標不能進行。夥伴關係可以在活動過程中解除，但是會受到一定懲罰。|2.申請夥伴有24小時的時間限制，超過時間後申請將會作廢。同時，只有等級相差不超過20級的玩家間才能結為夥伴關係。|3.每天活動會安排5對不同的目標，每一對目標都需要夥伴雙方分別完成後才能獲得默契度。目標任務開始前雙方中的任一人可以分配目標，分配完成後不能更改。目標必須在分配完成後才會開始並記錄進度，請務必提前分配。|4.每天的目標中會有一個特殊的“挑戰”目標，每天有兩個不同的BOSS供玩家挑戰，同樣需要分配給夥伴雙方分別完成，完成後獲得的默契度為雙方造成的傷害進行折算後相加。挑戰目標在完成前可以不限次數嘗試，每次挑戰過後可以選擇是否將該次戰鬥結果錄入最終結果，錄入結果後挑戰目標才算作完成。|5.活動期間可以選擇解除夥伴關係。解除夥伴申請提出後會保留24小時，24小時內若對方未作出回應，則默認為同意解除關係。同時，當解除夥伴申請被拒絕一次後，可以花費鑽石強制解除解除夥伴關係。|6.每天的目標全部完成後，都會獲得一份獎勵；同時，完成了五天中的全部目標後還會額外獲得一個稀有“秀恩愛”頭像框！活動結束後，根據全服默契值排名還有限量顏良皮膚相贈，請不要錯過~",
