		{
			"SKYCITY_HARD_RULE",
			"1、玩家在通關了天空之城普通100層之後，即可切換到精英層。|2、普通層與精英層互不幹涉，皆可進行獨立操作。|3、精英層一共20層，從1層開始，通關該層才能進入下一層。|4、精英層每個關卡的挑戰需要消耗1張天空之城挑戰券，挑戰券可在普通層獲得。挑戰券不足則無法進行挑戰。|5、掃蕩只能掃已通過的層數。|6、精英層每層皆可獨立掃蕩，掃蕩幾次即消耗幾張挑戰券。|7、只有通關此層關卡，才能得到此層的獎勵。|8、戰鬥可以手動進行，也可以在通關一次後使用掃蕩功能。|9、點擊右側按鈕即可選擇跳轉層數，無法跳轉到上一層未打通的層數。|10、每日每層皆有三次免費的掃蕩機會，無次數可點擊按鈕進行購買。|11、每層皆有練習模式，練習模式難度與該層難度一致。|12、練習不消耗挑戰券也不產出獎勵，每次挑戰只需消耗10000金幣。|12、無論通關與否，皆可進行練習。",
