		{
			"INSCRIPTION_RULE_TXT",
			"1、戰姬達到100級並完成血脈甦醒後，開啟徽章系統及該戰姬屬性面板上的徽章鑲嵌接口。|2、徽章分為資優生、模範生、特長生三種，每種徽章所能加成的屬性範圍會有差異。此外還有神秘的套裝獎學金徽章等著各位學長。|3、製作不同類型的徽章需要消耗對應的星晶材料，製作頂級徽章需要額外消耗徽章之心。|4、製作獲得的徽章會隨機獲得一條初始加成屬性。|5、重鑄會改變徽章所加成的屬性類型，但加成的值不會發生變化；重鑄後的屬性類型需要保存，否則重鑄效果將不會保留。但是套裝徽章不可以重鑄。|6、等級越高的徽章加成的效果越強。|7、製作的徽章等級不同，消耗的材料數量不同。|8、製作好的徽章需要在戰姬屬性面板進行穿戴。|8、套裝獎學金徽章在重鑄和製作7級徽章時候有幾率獲得，此外還能在每日任務里獲得，每天獎勵的獎學金徽章都不相同，務必每天去看看哦。只有裝備了全部的套裝徽章才能激活套裝屬性。",
