		{
			"TREASURE_RULE_TEXT",
			"1.14級以上的學長可以進行打工，隨著學院等級的提高，可以去更多的場所打工|2.派學妹出發去打工需要消耗霜激凌，霜激凌是學院提供的，每個小時提供3個|3.不同的戰姬適合在不同的場所打工，每個戰姬可以打工的地域只有一個|4.除了在未來科技工廠外，其他地區打工的隊伍在打工中有可能會遇到競爭對手或是獲得額外獎勵，隊伍成員的平均戰力越高，戰勝競爭對手的幾率越高|5.部分戰姬擁有特殊能力，可以增加打工效率、減少消耗霜激凌數量、提高遇到競爭對手或額外獎勵的幾率等|6.參加打工的學妹人數、等級、品階、星級等會影響打工的基礎獎勵數額|7.42級之後每天5:00有幾率出現帶有額外賞金的打工，完成後有鑽石獎勵|8.VIP4以上的學長在打工中可以獲得1.5倍的基礎和鑽石獎勵；VIP7以上的學長可以獲得2倍的基礎和鑽石獎勵",
