		{
			"ACTIVITY_SAKURA2_RULE_TEXT",
			"    又到了櫻花紛飛的季節，這一次，學院內出現了一位神秘的身穿櫻花圖案衣服的少女，她似乎在尋找些什麼。那麼，同樣在參加櫻花祭的你，是否能夠遇見這位神秘的少女，又是否能夠幫助她找尋到她所丟失的東西呢？相約在櫻花祭的故事，等你來開啟——||1.活動期間，玩家可以通過完成普通或精英副本獲取『糯米』，通過從飲料機購買飲料獲取『豆沙』（抽卡券與打折券除外），通過參加全國制霸戰鬥獲取『櫻花』；也可以通過在櫻花祭超值禮盒活動中購買限定食材禮盒來獲取這三種材料。|2.在菓子工坊中，可以將至少兩種食材製作成櫻花點心。|3.在賞櫻大會中，將之前製作好的點心用來賞櫻，將會遇到隨機的事件，從而獲取不同的道具獎勵或限定戰姬契約書——她最喜歡的點心是『櫻餅』喲！但是也要注意，逃走或是被打敗是沒有任何獎勵的。|4.在櫻花大戰中，將為你帶來與這位神秘少女相遇以及並肩戰鬥的故事。在這裡可以獲得櫻花祭限定頭像框以及『她』的專屬頭像喲！限定戰姬『千本櫻』在櫻花大戰中將會獲得100%的血量、物攻與法強加成，同時，嚮導荀和與劉禪也會獲得50%的血量、物攻與法強加成。",
