		{
			"TEACHER_RULE",
			"叮咚~叮咚~班級開課啦，快去尋找屬於自己的老師和學生吧！|1.本功能不可跨服，一名老師最多可以擁有一名學生，一名學生也最多可以擁有一名老師，只要滿足條件，可以同時擁有老師和學生兩種身份，但是不可以同時與同一個人結成兩種班級關係哦。|2.成為學生的條件：玩家的學院等級大於等於10級小於90級，當前沒有老師|成為老師的條件：玩家的學院等級大於等於60級，老師的等級要大於徒弟3級以上，當前沒有學生|3.一天可以向3名不同的玩家發出申請，申請超過48小時自動失效。|4.當你加入一個班級時，自動將對方加入好友列表。這樣你就可以與自己的老師/學生送禮啦，不僅可以得到友情幣獎勵，並且會增加與對方的100親密度，每日一次，每日親密度上限增加100，最高3000。親密度越高，學生額外獲得的經驗越多。當親密度為0時，一點體力額外獲得0.25經驗；親密度為1000時，一點體力額外獲得0.5經驗；親密度為2000時，一點體力額外獲得0.75經驗，當親密度達到3000時，一點體力額外獲得1點經驗。|5.老師會給學生佈置課後作業，當學生每完成一個任務時，老師則可以獲得獎勵。具體任務請在課後作業里查看哦。部份任務會隨著班級的解散而重置。|6.當優秀學生完成校園旅程的任務時，也會獲得對應的獎學金，具體請在校園旅程里查看|7.主動提出解除關係的一方可以立即與對方解除關係，但是會受到停課的懲罰，必須等待24小時才能加入下一個班級，對方則不會有任何懲罰。建立關係未滿24小時不可以解除哦。關係解除後雙方親密度清零。|8.當學生達到90級時，會開啟畢業測驗的任務，通關此考驗領取獎勵即可畢業，師徒關係也會自動解除。",
