		{
			"ZHUGE_RULE_TITLE",
			"孔明の迷失森林規則說明",
			""
		},
		{
			"ZHUGE_RULE_CONTENT",
			"    那個神秘人口中說的“諸葛亮姬”究竟是什麼人？接受了偉大使命的由三人帶領的小隊踏上了旅途，真相等待她們去揭開——||【冒險前的準備】|1.開始冒險前，可以自由選擇由15名戰姬與3隻寵物所構成的冒險小隊，出發去冒險！|2.如果你擁有戰姬數量或者強度不足也沒有關係，你可以通過“傭兵”按鈕花費鑽石來自由的招募你沒有的戰姬喔~|3.冒險中所有戰姬等級會變為100級紅+1品質！|4.如果在冒險小隊中攜帶的戰姬帶有“號召力”技能，將允許你額外選擇幾位戰姬參加冒險喔！||【冒險途中須知】|1.開始冒險後，可以隨意選擇一個區域進入森林，在進入森林後點擊相鄰的區域即可進行探索。|2.每進入一個區域，都會觸發這個區域的不同事件，會有怎樣的選擇等待著你呢？|3.隨著在迷失森林中探索，森林中的地形會在魔法的影響下時刻變化，要小心喔。|4.每探索一個區域都會消耗1點基礎探索體力，有時會根據探索的難易度（進行一次探索後顯示在區塊右下角）消耗額外探索體力，此時再次點擊該區域即可消耗相應體力探索了喔。需要注意的是，點擊進入已經探索完畢的灰色區域也會消耗1點體力。|5.可以通過消費鑽石購買食物或享用野餐盒（每累儲100鑽獲取）補充探索體力。|5.部分戰姬擁有冒險時的專有技能，在部分事件觸發時會有概率發動技能從而影響事件結果喔！技能在戰姬頭像右上角有“閃電”標示，可以在選擇和查看陣容時長按戰姬頭像查看。||【通過森林之後】|1.在第一次穿過迷失森林後，將會解鎖全新的劇情與功能，在森林中拿到的重要道具“魔盒元件”將會成為與她相遇的契機，請盡可能獲得吧！|2.通過森林後，將會開啟“自由冒險”功能，只需要提供相應的儲備體力，你的戰姬將會自主前往森林冒險、獲取寶物！",
