			"1、玩家達到100級後開放報名失落校區的資格。|2、失落校區每月1~5日報名，6日準備，7日正式開啟戰鬥，27日進行排名和獎勵的結算，若未在1~5日報名，則本月將無法參與，因此請及時在每月初5天進行報名。|3、系統將會根據報名玩家數量，從報名的玩家中隨機匹配3~5名玩家為對手。|4、每局出生位置隨機分配，玩家可在6日準備階段時，查看自己被分配的出生點。|5、戰鬥開始後，玩家需要利用初始資源招募戰姬進行編組，搶佔更多的資源產出地區。自身圖書架，課本和覺醒狀態等不生效。|6、戰姬隊伍執行命令時需要消耗2個能量糖果，若能量糖果不足，則無法派遣更多的戰姬隊伍執行命令。|7、招募普通戰姬需要消耗生命之水，資源不足時無法招募。|8、招募Sx戰姬將會增加絢爛玫瑰的“維持消耗量”，絢爛玫瑰的“維持消耗量”與擁有數量相同或者更少時，將無法再招募更多Sx戰姬。|9、若絢爛玫瑰的產區被敵人奪走，則可能讓該資源的“維持消耗量”入不敷出，這將導致玩家所有已招募的Sx戰姬全屬性大幅度下降，資源缺少的越多，屬性下降的越多。|10、戰鬥期間每天分為9~14、14~19、19~24點共3個回合，每回合前4.5小時玩家可任意發佈或撤銷命令，後0.5小時為回合行動階段，屆時無法撤銷或發佈命令。每次行動都需要消耗行動點。|11、每天每場戰鬥結束後，戰姬的血量值和能量值都將保存，同時戰姬每回合將會恢復一定生命值。|12、切記不可孤軍深入，戰姬只有所處區域和出生點相連時才能維持全盛狀態，若被其他玩家切斷後路，則被切斷後路的戰姬全屬性都將大幅度下降，同時將無法恢復生命值。|13、佔領Buff區域將會獲得Buff加成，佔領的Buff區域數量越多，獲得的加成Buff數量越多。|14、大部分區域初期沒有資源產量，但隨著遊戲進度，將會逐步開放產出資源。|15、佔領一塊校區中所有區域，將會使該校區的所有區域資源產量翻倍。|16、與自身佔領區域相鄰的校區，其所有區域將會被戰爭迷霧籠罩，可以查看粗略的資源產出類型，但無法查看具體產出數量和戰姬配置，未相鄰的校區將會被白雲籠罩，無法查看任何信息。|17、無論佔領區域數量多寡，佔領讀書頂之球核心區的玩家必定為第一名，其次將根據佔玩家領區域的數量決定排名。|18、佔有相同數量且未佔有讀書頂之球區域的玩家，將會根據玩家數量，領取最低的排名獎勵（例如三名玩家同時排名第二，則三名玩家皆領取第四名的排名獎勵，所以要盡可能的搶佔其他玩家的區域哦~）。|19、除卻排名獎勵，玩家還將根據佔有的區域數量獲得額外的區域獎勵。|20、排名獎勵和區域獎勵給與玩家的橄欖草，可以用於在失落校區商店中購買高級裝備和道具。",
			""
		},
