		{
			"SUMMER_GOLDFISH_RULE_TEXT1",
			"    新的一年夏日祭來臨，自從去年夏日祭上的撈金魚攤位被未知人士莫名炸掉（關羽：阿嚏！）後，夏侯淵就自告奮勇當起了撈金魚攤位的店老闆，由她來經營的攤位究竟是什麼樣的呢，一起來看看吧~|1.活動期間，打開當天的每個日常任務活躍度寶箱都可以獲得1個普通的撈金魚用紙網，周活躍寶箱不能獲得紙網。|2.除了免費獲取外，也可以通過花費鑽石直接購買普通紙網。|3.店老闆額外推薦一種更加稀有的高級紙網，並且承諾使用這種高級紙網捕撈到的金魚可以獲得1.5倍積分獎勵喲！這種特殊的紙網在活動期間通過每次累計儲值300鑽都可以獲得10個。|4.點擊魚池中的金魚，就可以使用紙網來撈取金魚啦，但是撈魚不是必定成功的，無論成功與否都會失敗後會消耗紙網。|5.撈到不同顏色的金魚會獲得不同的積分獎勵，積分可以用來兌換物品獎勵。使用普通紙網捕撈到不同金魚的積分獎勵如下：",
