			"   感謝學長的守護，流氓已經被擊退出校園。但學妹又有了新的煩惱，她們在回校途中將自己隨身攜帶的相片遺失在了校園各處，請學長們幫助我們的學妹找回她們的回憶吧！|1.戰姬頭像處代表了戰姬遺落相簿的地方，學長點擊該學妹頭像即可進入該地進行探索。|2.幫助不同的學妹找到相簿會得到不同的獎勵。|3.進入挑戰學妹的相簿後，可能會遇到其他的學長與您進行爭搶，與學長們戰鬥需要消耗體力，越高層的學長戰鬥力越高，您需要消耗的體力會更多，但是您會獲得的獎勵也會越好。|4.戰勝其他學長後您會得到記憶相簿的鑰匙，不同顏色的鑰匙對應著不同顏色的相簿，您需要有鑰匙才可以將相簿打開。|5.每一頁都有一位最厲害的學長鎮守在門口前，打敗那位學長您就可以進入下一頁回憶了。|6.通關回憶錄三頁之後，您將會獲得額外獎勵，請學長努力通關吧~|7.放棄此次回憶後，您可以重新選擇戰姬幫忙找尋回憶哦~每天不限制次數。|8.點擊返回即可回到主界面，再次進入會保留您上次的進度哦~|9.已經死亡的戰姬在此次探尋中不能再出戰，但可以使用復活功能使其復活，但要消耗較大的代價。",
