		{
			"SUMMER_QUIZ_RULE_TEXT",
			"    在本屆夏日祭最大的舞台上，幕布緊閉著，一場盛大的活動正在醞釀著——|1.活動期間，每天20點即可開啟智勇大闖關。想要參加闖關的學長，請務必提前進入活動界面等候。|2.智勇闖關中，學長們將會面對智力考驗——答題，以及勇氣考驗——擊敗木頭人，一共要闖過20關考驗才算通關。通關後，從20點開始到通關的時間算作你的通關時間，並且據此計算排名和發放排名獎勵。|3.題目回答錯誤時，將會受到失誤懲罰而在15秒內不能繼續答題，此時可以等待懲罰時間經過，也可以花費鑽石來購買復活來跳過懲罰時間。|4.在擊敗木頭人考驗中，所有戰姬強度將平衡至100級紅1，木頭人不會進行攻擊，但是只有部分戰姬能夠對它造成傷害，請仔細閱讀戰鬥前的提示進行戰鬥喔！",
