		{
			"AUCTION_RULES",
			"因為校區的戰鬥非常激烈，學院急需一大筆資金來修繕校區，戰姬們紛紛獻出自己的珍藏舉辦愛心拍賣會，希望能夠早日湊齊所需資金!歡迎學長們積極獻出自己的愛心哦。|1、拍賣時間為每日的5:00至21:30。21:30以後只能入場參觀當日拍賣的物品，無法參與競拍，次日5:00拍賣物品才會上新。|2、拍賣分為本服模式和跨服模式。跨服為全服務器都可參與。本服僅本服可參與。每次出價不能小於當前最高價格的1%。|3、刷新按鈕可以刷新當前最高出價，請務必在出價前刷新一下哦。當學長的出價被超過，請去郵箱領取拍賣出資哦。競拍物品也是通過郵箱查收。|4、點擊圖標可以查看物品的詳情，其餘可以參與競價。|5、拍賣不僅有成就還有專屬的頭像和兩種不同的花之旅途頭像框，請學長多多關注~|6、在拍賣行拍賣物品消耗的鑽石，都不會計入消費活動和每日任務里。",
