			"VOTE_SUMUP_MAIL_TEXT",
			"親愛的學長，感謝您在學妹人氣大比拼中的熱情參與，本屆人氣大比拼中的人氣冠軍為%s，大賽組委會將會在今後的一段時間內為她製作全新的造型，在新造型推出時您將獲得購買造型的折扣：%d，請繼續密切關注并支持她，謝謝！",
