		{
			"VOTE_RULE_TITLE",
			"人氣大比拼活動規則",
			""
		},
		{
			"VOTE_RULE_TEXT",
			"    學園發展至今，已經有超過一百名學妹在這所學園中共同學習生活、並肩戰鬥了，這些學妹中你最喜歡的是哪一位呢？快來為她投出寶貴的一票吧！||1.活動期間，打開當天的每個日常任務活躍度寶箱都可以獲得2張普通人氣票，周活躍寶箱不能獲得人氣票。|2.除了免費獲取外，也可以在投票界面通過花費鑽石直接購買普通人氣票。|3.除了普通選票外，活動期間每累計儲值300鑽可以獲得一張超級人氣票，超級人氣票的票數會暫時隱藏直到活動結束前的3天，它可以一次性為你所喜愛的戰姬增加50票，除此之外還可以使戰姬獲得一份神秘禮物喔！|4.當戰姬擁有神秘禮物時，玩家每一次為他投普通票都將有概率獲得一份禮物，禮物包含全新戰姬“悠悠少女-張寶”的契約書，一次性投多張票獲得概率可以疊加，但一次最多只能獲得1份禮物喔。|5.在神秘禮物發放完畢後，投出超級票的玩家也會獲得包含張寶契約書的回饋獎勵，契約書數量與禮物發放完畢前其他玩家給這位戰姬投票數量有關。|6.在活動開啟的前兩天，可以免費選擇一位戰姬為你的支持戰姬，如果活動結束後該戰姬奪得人氣冠軍，那麼你會得到一份特殊的支持獎勵喔！|7.活動結束後，我們將會為奪得人氣冠軍的戰姬製作全新的造型，同時為人氣冠軍投票最多的學長將會獲得給新造型冠名的權利，並且免費獲得該造型、以及獨一無二的造型冠名者專屬頭像！而其他學長在活動期間投出的所有票，都將會換算成ta購買該造型的個人折扣。新造型將會在活動結束後1-2個月內揭曉，盡請期待！",
