			"ACTIVITY_LOTTERY_RULE_TEXT",
			"1.活動期間，每累計儲值60鑽即可獲得一次選擇幸運數字的機會。|2.每次可以從給定的數字中任意選擇，但是不能選擇其他學長已經選擇的數字。|3.活動結束前每天5:00將會揭曉當期大獎數字以及10個幸運數字，同時開啟下一期大獎選號。|4.新一期大獎選號開始後，上一期還未使用的選號機會可以繼續使用。|5.每期大獎獎勵各不相同，幸運獎獎勵固定為8888鑽石。|6.每期大樂透獲得大獎的幸運學長將會額外獲得二週年限定實體獎品，屆時請獲得大獎的學長關注GM消息喔~",
