		{
			"ANNI2_RULE_TEXT",
			"1.活動期間，帶領參戰的戰姬通關所有活動副本，即可獲取寶箱中的豐厚獎勵。|2.每個大關都有三場不同的戰鬥，勝利後各可獲得一顆星，每場戰鬥通關前都可以不限次數挑戰，但要注意戰姬的狀態會在戰後保留，要謹慎地挑戰喔。|3.通過完成戰姬提出的任務，即可邀請戰姬參戰，但是請在戰姬離開前完成她的任務。|4.部分戰姬需要交付一定數量的秘密鎖匙才能夠邀請，但是要注意交付後若沒有完成所有任務成功邀請戰姬，物品不會退還喔。|5.每次會隨機出現5位待邀請戰姬，戰姬出現後若未邀請成功經過24小時便會離開，可以花費鑽石來手動將未邀請成功的戰姬替換為新戰姬，所有新戰姬的任務進度從0開始計算。|6.在戰鬥中陣亡的戰姬會與未邀請的戰姬一同離開休息，在離開後她還有機會再次作為待邀請戰姬出現。|7.帶領邀請的戰姬每通過5次活動副本就會獲得2張該戰姬的契約書，戰姬陣亡後累計次數消失，但是要注意VIP等級不足時部分戰姬的契約書無法獲得喔。",
