		},
		{
			"CREATS_RULE3",
			"1、秘術爭奪由多個獨立的副本構成。|2、每個副本都需要足夠數量的玩家參與才能開啟。|3、每個玩家參與副本都需要消耗一份秘術卷軸。|4、秘術卷軸通過玩家日常行為消耗的體力累計、每消耗3000點體力獲得一份秘術卷軸。|5、當玩家秘術卷軸持有數量達到上限後、將無法繼續積累。|6、同服組隊沒有戰力限制，學院等級差在五等以內的玩家可以加入跨服組隊。|7、單人可以通過單人模式開啟秘術爭奪副本的挑戰。|8、單人模式中的敵人的強度同於多人模式，但單人模式中玩家將擁有更多的派遣名額。|9、單人模式的獎勵結算機制與多人模式相同。",
