			"CREATS_RULE5",
			"1、每個副本由多個據點構成、據點由通路鏈接、每個據點都會有數組敵人。未開啟的關卡為灰色顯示，可以挑戰的關卡高亮顯示。|2、副本地圖因boss特性會有不同的副本buff。|3、每組敵人都可以通過單人戰鬥或者合作挑戰方式進行攻擊。|4、每組敵人同一時間只能開啟一場戰鬥|5、每組敵人的挑戰都會有1分鐘的選人時限，超過將重新退出當前戰鬥選人。|6、戰鬥結束後、玩家派遣的戰姬和敵人的狀態會被保存，寵物能量在戰鬥開始重新計算。|7、每派遣一個沒有上陣過的戰姬上場、將會消耗一個派遣名額、派遣名額耗盡後、只能派遣已經上陣過的戰姬上場。|8、副本剩餘時間不足2分半時，無法開啟新的戰鬥。",
