		{
			"CAMP_WAR_RULES_TEXT",
			"天使米迦勒與墮天使路西法墜入學院，整個校園分崩離析。爲了爭奪學妹世界的主權，兩個天使開始集結自己的勢力，召喚各位學長加入，並為他們爭奪校園里分裂的各個學院。|1、玩家須選擇一方陣營加入，加入陣營後即可參與爭奪戰活動|2、加入陣營後，本次活動期間不可轉陣營|3、一方陣營人數過多時，會造成擁擠現象，請您稍後再選擇加入此陣營，您也可以選擇加入另一個陣營哦~|4、爭奪戰開始後，每隔一段時間會開啟一些學院的攻打|5、佔領了學院後，該學院會有一段時間的免戰時間，此時該學院不可進行攻打操作。|6、已被佔領的學院和陣營的起始學院可以派兵駐守|7、免戰結束後，敵對陣營只要打敗了佔領該學院的陣營在該學院的所有駐守隊伍，即可佔領該學院|8、只能攻打相連的臨近學院，可以直接從編隊中選擇一個隊伍出戰，不管該隊伍現在駐守在任何學院|9、所有戰姬寵物在陣營戰中皆為紅一滿級品質|10、擊敗守護學院者和擊敗敵對玩家皆會有本陣營的功勛獎勵，功勛可以兌換戰姬契約書，但獲得敵對陣營戰姬契約書需要的功勛會較高。|11、若雙方陣營一起攻打同一座城的守護學院者，則先將守護學院者的血量打完者佔領此城並且可以獲得擊敗該學院的結算功勛，功勛按玩家累計傷害結算，若該守護學院者已先被敵對陣營擊敗，則我方陣營無法獲得此學院的功勛結算。|12、戰姬在駐守學院時被挑戰，勝利也會獲得擊敗敵對戰姬的功勛|13、陣營戰中，記錄所有戰姬的血量和能量的變化，若戰姬死亡，則只能使用生命之泉進行復活，寵物不會死亡，但會清空能量|14、在陣營戰中勝利的一方陣營將會有額外的功勛獎勵，爭奪戰結束後的一天仍可以進行戰姬兌換。|15、擊敗一個戰姬可獲得10功勛，擊敗守城人的功勳獎勵將按照您的累計傷害量來計算。|16、陣營任務每天皆會重置，攻打守城人也算進攻勝利一次哦~|17、與該陣營主學院相鄰的兩座學院，該陣營玩家的駐守隊伍將會有增益buff，敵對陣營玩家將其攻下將會更困難。|18、進攻敵對陣營學院將匹配到該學院最新的駐守隊伍，以此類推。防守成功也會獲得功勛的哦~|19、爭奪戰結束後，佔領較多學院的一方陣營獲勝，獲勝的陣營中有貢獻的學長將直接獲得1000點功勛。若雙方打平，則雙方分別獲得500點功勛。雙方陣營的總功勛第一名及第二至一百名皆有頭像框獎勵哦~本次活動結束後，未兌換完的功勛會保留到下次活動開啟哦~",
