		{
			"LIANYI_GIVE_RULE_TEXT",
			"1、又是開學的季節，一起來參加聯誼吧！通過贈送禮物可以增加你的人脈，收取禮物則可以增加魅力，人脈或魅力達到一定值可以領取豐富的獎勵！|2、禮物需要通過消耗材料來製作，材料一共有三種，限定版説明書、家政課手冊、工藝課手冊。|3、通關任意劇情或精英副本有幾率獲得家政課手冊，參與上頂樓或鬥牛有幾率獲得工藝課手冊，限定版説明書衹能通過幸運大轉盤獲得。|4、采用不同的材料配方，製作出來的禮物也會有所區別。|5、贈送禮物可以贈送任意種類、任意數量的禮物。|6、收禮記錄中能查看最多30條的收禮記錄，并且可以選擇回贈禮物。|7、贈送1個以上的同種紅色禮物、10個以上的同種橙色禮物或30個以上的同種紫色禮物都會播放全服廣播。|8、本次活動結束後，人脈和魅力前100名的玩家會分別獲得開學季人脈頭像框和魅力頭像框，人脈和魅力第1名的玩家則會分別獲得人脈王頭像框和魅力王頭像框。|9、活動期間每纍計儲值300鉆會獲得一個稀有禮物，贈送和收取稀有禮物獲得的人脈值和魅力值會比一般的禮物要高很多。|10、祝學長們聯誼玩得開心，收禮收到手軟！",
