		{
			"LEGEND_ARENA_RULE_TEXT",
			"1.每周五的21點，見習組的前1000名玩家和高階組的前100名玩家獲得參加晉級賽的資格。|2.每周五的21點，高階組的后3000名玩家和大師組的后300名玩家會成爲晉級賽被挑戰的對象。|3.晉級賽開始后，系統會隨機匹配給玩家三名上級段位的對手，玩家可以挑戰任意一位對手，但是第一次挑戰后就衹能繼續挑戰該對手，無法挑戰其他人。|4、晉級賽持續到第二天的21點，期間玩家有三次挑戰機會，若取得兩次勝利則晉級成功，否則晉級失敗。|5.晉級賽每次挑戰機會之間有1個小時的冷卻時間。|6.晉級賽采用的賽制與被挑戰方所在段位的賽制相同。|7.若晉級成功，則與被挑戰方交換段位、排名和積分；若晉級失敗則保持不變。|8.晉級賽期間，被挑戰方仍然可以正常地在本段位挑戰和被挑戰，挑戰方也可以正常被本段位玩家挑戰，若挑戰方晉級成功，交換的是晉級成功時雙方最終的排名和段位。",
